{
  "implementation": "import math

def solve(case):
    payload = case['payload']
    matrix = payload['matrix']
    if not matrix or not isinstance(matrix, list):
        raise ValueError('matrix must be a nonempty list')
    n_rows = len(matrix)
    if n_rows == 0:
        raise ValueError('matrix has no rows')
    n_cols = len(matrix[0])
    if n_cols == 0:
        raise ValueError('matrix has no columns')
    for row in matrix:
        if len(row) != n_cols:
            raise ValueError('rows have inconsistent lengths')
    is_square = (n_rows == n_cols)
    # Compute document frequency per column
    df = [0] * n_cols
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                df[j] += 1
    # Compute IDF
    idf = [0.0] * n_cols
    for j in range(n_cols):
        idf[j] = math.log(1.0 + n_rows / (1.0 + df[j]))
    # Build weighted matrix (sparse) and degree
    weighted_matrix = []
    degree = []
    for i, row in enumerate(matrix):
        row_sparse = []
        row_degree = 0.0
        for j, val in enumerate(row):
            if val != 0:
                if is_square and i == j:
                    # self-similarity removed
                    continue
                w = val * idf[j]
                row_sparse.append((j, round(w, 6)))
                row_degree += w
        weighted_matrix.append(row_sparse)
        degree.append(round(row_degree, 6))
    # Round idf
    idf_rounded = [round(v, 6) for v in idf]
    return {
        'idf': idf_rounded,
        'weighted_matrix': weighted_matrix,
        'degree': degree
    }"
}
